un AS (SELECT c FROM UNNEST(SPLIT('121005 121010 122105 122305 122405 122505 122520 122610 122620 122735 122745 123105 123110 123115 123205 123210 123305 123310 123405 123605 123805 142340 142345 142355 142505 142510 142515 142520 142530 142535 142705 201110 202105 252605 252705 252710 252715 252725 253120 253210 253215 253220 253225 253305 253405 253410 254305 254310 254405 254410 254415 254420 254505 261730 261905 271105 271110 312310 318505 318510 318605 318610 318705 320110 322120 322140 322605 331105 331110 331205 331305 332105 332205 333105 333110 333115 334105 334110 334115 342110 342115 342120 342125 342610 373105 373130 373135 373140 373145 373220 373225 376315 376320 420105 420110 420115 420120 420125 420130 420135 423105 423110 423115 510105 510205 510305 510310 514310 514330 519205 519210 519215 519305 519310 519315 519320 519910 519920 519930 520105 520110 725505 760205 760305 760310 764005 773505 773510 774105 780105 782405 782410 782415 791110 813115 813125 820110 820205 820210 842120 122115 122205 122515 122615 122705 122725 122730 123705 142525 142710 201225 202110 202120 226105 226305 226310 226315 252720 253125 253130 253205 254105 254205 261910 311405 311410 318710 319105 319205 322105 322135 342105 342605 351905 351910 373230 376305 724605 725510 760505 761005 761210 761215 791105 791115 791120 791130 791135 791140 791145 813120 813130 820105 842110 122755 123410 201105 201205 201210 201215 202115 253135 261705 320105 516915 813110 254110 820125 842135 122110 122510 122715 122740 122750 142350 201115 201220 319110 322125 376110 376310 376330 724610 765405 813105 820115 820120 122605 122720 376105 516810 516905 761245 791125 122710 373115 373205 373210 373215 791155 791160 516805 122120 226320 516910 791150 322115 376325 373120 226110 261720 373110',' ')) c),
b AS (SELECT sigla_uf uf, cbo_2002 c, SUBSTR(cnae_2,1,2) d, COUNT(*) q FROM `basedosdados.br_me_rais.microdados_vinculos` WHERE ano=2025 AND vinculo_ativo_3112='1' AND valor_remuneracao_media>0 GROUP BY 1,2,3),
s AS (SELECT uf, CASE WHEN d IN ('01','02','03') THEN 'A' WHEN d BETWEEN '05' AND '09' THEN 'B' WHEN d BETWEEN '10' AND '33' THEN 'C' WHEN d='35' THEN 'D' WHEN d BETWEEN '36' AND '39' THEN 'E' WHEN d BETWEEN '41' AND '43' THEN 'F' WHEN d BETWEEN '45' AND '47' THEN 'G' WHEN d BETWEEN '49' AND '53' THEN 'H' WHEN d IN ('55','56') THEN 'I' WHEN d BETWEEN '58' AND '63' THEN 'J' WHEN d BETWEEN '64' AND '66' THEN 'K' WHEN d='68' THEN 'L' WHEN d BETWEEN '69' AND '75' THEN 'M' WHEN d BETWEEN '77' AND '82' THEN 'N' WHEN d='84' THEN 'O' WHEN d='85' THEN 'P' WHEN d BETWEEN '86' AND '88' THEN 'Q' WHEN d BETWEEN '90' AND '93' THEN 'R' WHEN d BETWEEN '94' AND '96' THEN 'S' WHEN d='97' THEN 'T' WHEN d='99' THEN 'U' ELSE 'X' END sec, d, q, b.c c,
  (z.c IS NOT NULL) isz, n.e14, n.e34, (un.c IS NOT NULL) isu FROM b LEFT JOIN z ON z.c=b.c LEFT JOIN n ON n.c=b.c LEFT JOIN un ON un.c=b.c)
SELECT uf, STRING_AGG(CONCAT(sec,':',CAST(tot AS STRING),':',CAST(mp AS STRING),':',CAST(ROUND(s14) AS STRING),':',CAST(ROUND(s34) AS STRING)), '|' ORDER BY sec) r FROM (
SELECT uf, sec, SUM(IF(isz OR e14 IS NOT NULL OR isu, q, 0)) tot, SUM(IF(isz OR e14 IS NOT NULL, q, 0)) mp, SUM(IF(e14 IS NOT NULL, q*e14, 0)) s14, SUM(IF(e14 IS NOT NULL, q*e34, 0)) s34 FROM s GROUP BY uf, sec) GROUP BY uf ORDER BY uf